// Package cli implements the csvstat command line.
package cli

import (
	"errors"
	"flag"
	"fmt"
	"io"
)

const (
	exitOK    = 0
	exitUsage = 2
)

// Run executes csvstat with the given arguments and returns the process exit code.
// Diagnostics go to stderr; stdout carries only profile output.
func Run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("csvstat", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {
		fmt.Fprintln(stderr, "usage: csvstat FILE")
		fs.PrintDefaults()
	}

	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return exitUsage
		}
		return exitUsage
	}

	if fs.NArg() != 1 {
		fmt.Fprintln(stderr, "csvstat: expected exactly one FILE argument")
		fs.Usage()
		return exitUsage
	}

	// Profiling is not implemented yet; later stories read FILE and write output here.
	return exitOK
}

