package cli

import (
	"bytes"
	"testing"
)

func TestRunReturnsExitCode(t *testing.T) {
	tests := []struct {
		name string
		args []string
		want int
	}{
		{name: "no arguments", args: nil, want: 2},
		{name: "two files", args: []string{"a.csv", "b.csv"}, want: 2},
		{name: "unknown flag", args: []string{"--bogus", "a.csv"}, want: 2},
		{name: "help flag", args: []string{"-h"}, want: 2},
		{name: "one file", args: []string{"a.csv"}, want: 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var stdout, stderr bytes.Buffer
			got := Run(tt.args, &stdout, &stderr)
			if got != tt.want {
				t.Errorf("Run(%q) = %d, want %d", tt.args, got, tt.want)
			}
		})
	}
}

func TestRunWritesNothingToStdout(t *testing.T) {
	tests := []struct {
		name string
		args []string
	}{
		{name: "no arguments", args: nil},
		{name: "one file", args: []string{"a.csv"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var stdout, stderr bytes.Buffer
			Run(tt.args, &stdout, &stderr)
			if stdout.Len() != 0 {
				t.Errorf("Run(%q) wrote %q to stdout, want nothing", tt.args, stdout.String())
			}
		})
	}
}

